<?php	if (!isset($_GET['page'])) {		header("Location: ?page=1");		exit;	}	$page = (int) $_GET['page'];	$spritesPerPage = 300;		$begin = 1+(($page-1)*$spritesPerPage);	$end = $spritesPerPage + (($page-1)*$spritesPerPage);		$prevPageId = ($page > 1) ? $page-1 : 1;	$nextPageId = $page+1;	$nextPage = [		"begin" => (($nextPageId-1) * $spritesPerPage) + 1,		"end" => (($nextPageId-1) * $spritesPerPage) + $spritesPerPage	];	$prevPage = [		"begin" => (($prevPageId-1) * $spritesPerPage) + 1,		"end" => (($prevPageId-1) * $spritesPerPage) + $spritesPerPage	];?><!doctype HTML><html><head>	<style>		body {			/*background: red;*/		}		#navigation {			text-align: center;			margin-bottom: 10px;			width: 100%;			background: lightblue;			padding: 4px 0;		}		#navigation span{			margin: 0 10px;		}		#navigation a{			text-decoration: none;			color: rgb(80, 80, 80);			font: normal 14px "Arial";		}		#navigation a:hover {			color: rgb(0, 0, 0);		}		#sprites {			font-size: 0;			margin: 0 auto;			text-align: center;		}		.spritea {			margin: 0;			display: inline-block;			margin: -1px 0 0 -1px;			border: 1px solid #fff;			width: 32px;		}		.spritea img{			margin: 0;		}	</style></head><body>	<div id="navigation">		<a href="?page=<?php echo $prevPageId; ?>">Prev (<?php echo $prevPage["begin"]."-".$prevPage["end"]; ?>)</a>		<span>|</span>		<a href="?page=<?php echo $nextPageId; ?>">Next (<?php echo $nextPage["begin"]."-".$nextPage["end"]; ?>)</a>	</div>	<div id="sprites">		<?php			for ($sprite = $begin; $sprite <= $end; $sprite++) {				echo '<div class="spritea"><img src="sprite.php?id='.$sprite.'"/></div>';				if (($sprite%20) == 0) {					echo "<br/>";				}			}		?>	</div></body></html>